import 'dart:math';

List<String> separateParenGroups(String parenString) {
  int n = parenString.length;
  List<int> stack = [];
  List<List<int>> groups = [];

  for (int i = 0; i < n; ++i) {
    if (parenString[i] == '(') {
      stack.add(i);
    } else if (parenString[i] == ')') {
      if (stack.isNotEmpty) {
        int start = stack.removeLast();
        List<int> group = [start, i];
        groups.add(group);
      }
    }
  }

  // Sort the groups by their starting index
  groups.sort((a, b) => a[0].compareTo(b[0]));

  List<String> result = [];
  int prevEnd = -1;

  for (var group in groups) {
    int start = group[0], end = group[1];

    if (prevEnd + 1 <= start) {
      String substring = parenString.substring(prevEnd + 1, start);
      result.add(substring);
    }

    String groupStr = parenString.substring(start, end + 1);
    result.add(groupStr);

    prevEnd = end;
  }

  // Add remaining characters after last group
  if (prevEnd + 1 < n) {
    String remainder = parenString.substring(prevEnd + 1);
    result.add(remainder);
  }

  return result;
}
