int fib4(int n) {
  if (n <= 1) return n;

  final Map<int, int> memo = {};
  _fib(n, memo);
  return memo[n]!;
}

void _fib(int n, Map<int, int> memo) {
  if (memo.containsKey(n)) return;

  if (n == 0 || n == 1) {
    memo[n] = n;
    return;
  }

  final int prev = _fib(n - 2, memo)! + _fib(n - 1, memo)!;
  memo[n] = prev;
}
