bool isPalindrome(String text) {
  int length = text.length;
  if (length == 0 || length == 1) return true;

  int left = 0, right = length - 1;
  while (left < right) {
    // Check for non-alphanumeric characters and case-insensitivity
    bool skipLeft = false, skipRight = false;

    // Skip non-alphanumeric on the left side
    while (left < length && !isAlphanumeric(text[left])) {
      left++;
      skipLeft = true;
    }

    // Skip non-alphanumeric on the right side
    while (right >= 0 && !isAlphanumeric(text[right])) {
      right--;
      skipRight = true;
    }

    if (skipLeft && skipRight) {
      left++;
      right--;
      continue;
    } else if (skipLeft) {
      left++;
      continue;
    } else if (skipRight) {
      right--;
      continue;
    }

    final charLeft = text[left].toLowerCase();
    final charRight = text[right].toLowerCase();

    if (charLeft != charRight) {
      return false;
    }

    left++;
    right--;
  }

  return true;
}

