int smallestChange(List<int> arr) {
  if (arr.isEmpty || arr.length == 1) return 0;

  int n = arr.length;
  List<int> dp = List.filled(n, 0);
  for (var i = 0; i < n; i++) {
    dp[i] = i + 1;
  }

  for (var i = 0; i < n - 1; i++) {
    var x = arr[i];
    var y = arr[i + 1];

    if (x != y) {
      int minVal = min(x, y);
      int maxVal = max(x, y);

      // Check all elements between min and max
      for (var j = 0; j < n; j++) {
        if (arr[j] >= minVal && arr[j] <= maxVal) {
          dp[i + 1] = min(dp[i + 1], dp[j]);
        }
      }

      // Update the current element's value to be the minimum of its previous values
      dp[i] = min(dp[i], dp[i + 1]);
    } else {
      dp[i + 1] = dp[i];
    }
  }

  return dp[n - 1];
}
