class FFIHelper {
  static final _calloc = calloc;
  static final _free = calloc.free;

  static Pointer<Uint8> allocString(String str) {
    final byteData = utf8.encode(str);
    final pointer = _calloc.allocate(byteData.length + 1);
    _calloc.copy(pointer, byteData.buffer.asByteData(), 0, byteData.length);
    pointer[byteData.length] = 0;
    return pointer;
  }

  static String readString(Pointer<Uint8> ptr) {
    if (ptr == null || ptr.address == 0) return '';
    final bytes = Uint8.fromAddress(ptr.address);
    final length = bytes.indexOf(0);
    return utf8.decode(bytes.sublist(0, length));
  }
}

