  if (fileName == null || fileName.isEmpty || fileName.length > 256) {
    return 'Invalid';
  }

  // Check for invalid characters
  const Set<String> invalidChars = {r'\/:*?"<>|'};
  for (final char in fileName.split('')) {
    if (invalidChars.contains(char)) {
      return 'Invalid';
    }
  }

  // Additional check for reserved names on Windows
  final List<String> windowsReservedNames = [
    'CON', 'PRN', 'AUX', 'NUL',
    'COM1', 'COM2', 'COM3', 'COM4', 'COM5', 'COM6', 'COM7', 'COM8', 'COM9',
    'LPT1', 'LPT2', 'LPT3', 'LPT4', 'LPT5', 'LPT6', 'LPT7', 'LPT8', 'LPT9'
  ];

  // Check for reserved names with extensions (e.g., CON.txt)
  final String upperFileName = fileName.toUpperCase();
  for (final name in windowsReservedNames) {
    if (upperFileName.startsWith(name + '.') && 
        fileName.substring(name.length).split('.').length <= 1) {
      return 'Invalid';
    }
  }

  // Regular expression matching standard valid characters
  final RegExp validPattern = RegExp(r'^[a-zA-Z0-9_\-\.\s]+$');
  if (!validPattern.hasMatch(fileName)) {
    return 'Invalid';
  }

  return 'Valid';
}
